  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Modernism and a Changing World$j$, $j${"readings": [{"title": "Psalm 137 (King James Version)", "url": "/portal/bible/Psalms/137"}], "body": "In the early 1900s, the world changed quickly. Cities grew, factories spread, automobiles replaced wagons, and World War I shook the nation's confidence. American writers responded with a new style called Modernism. Modernist writers, such as F. Scott Fitzgerald, Ernest Hemingway, T. S. Eliot and Robert Frost, experimented with form, tone and subject.\n\nKey features of Modernism:\n1. Short, direct sentences, as in Hemingway's style.\n2. Fragmented structure and unusual forms.\n3. Disillusionment: a feeling that old promises had failed.\n4. Symbols and subtle meanings under a plain surface.\n5. Attention to loss, memory and the search for meaning.\n\nHistorical context shapes poetry. A poem written after a great war may mirror the concerns of its time: grief, uncertainty or hope for rebuilding.\n\nRead this original poem:\n\nThe town has quiet streets today,\nthe clocks are set, the doors are shut.\nWe counted what the years took away\nand learned to love what was left.\n\nConcerns of the time mirrored: loss after war, quiet recovery, resilience.\nTechnique: short lines, plain words, calm tone.\nComparison with an earlier style: Romantic poems often praised nature with elaborate images; this Modernist poem uses plain language to speak of loss.\n\nScripture connection: Joel 2:25 promises, And I will restore to you the years that the locust hath eaten.\n\nYour task: (1) Name the concerns of the historical period the poem mirrors. (2) Identify two Modernist features. (3) Compare the poem to a Romantic style in two sentences.\n\nFlorida standards: ELA.11.R.1.4, ELA.11.R.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.4, ELA.11.R.3.3", "script": "Welcome to the twentieth century. In the early nineteen hundreds, the world changed quickly. Cities grew, factories spread, automobiles replaced wagons, and World War One shook the confidence of the nation. American writers responded with a new style called Modernism.\n\nModernist writers include F. Scott Fitzgerald, Ernest Hemingway, T. S. Eliot and Robert Frost. They experimented with form, tone and subject.\n\nListen to the key features. Short, direct sentences, as in Hemingway's style. Fragmented structure and unusual forms. Disillusionment, which is a feeling that old promises had failed. Symbols and subtle meanings under a plain surface. And attention to loss, memory and the search for meaning.\n\nNow watch this. Historical context shapes poetry. A poem written after a great war may mirror the concerns of its time, such as grief, uncertainty or hope for rebuilding.\n\nLet us read an original poem. The town has quiet streets today, the clocks are set, the doors are shut. We counted what the years took away and learned to love what was left.\n\nThe concerns of the time are loss after war, quiet recovery and resilience. The techniques are short lines, plain words and a calm tone. And compared with a Romantic poem, which might praise nature with rich images, this Modernist poem uses plain language to speak of loss.\n\nAnd Scripture speaks to restoration. Joel chapter two, verse twenty five promises, And I will restore to you the years that the locust hath eaten.\n\nYour task today. Name the concerns of the historical period the poem mirrors. Identify two Modernist features. And compare the poem to a Romantic style in two sentences. Take the four question check when you finish.\n\nGod restores what the years have taken. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Modernism and a Changing World$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The Harlem Renaissance$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}], "body": "The Harlem Renaissance was a flowering of African American art, music and literature that centered in the Harlem neighborhood of New York City during the 1920s and 1930s. Poets such as Langston Hughes and Countee Cullen, and writers such as Zora Neale Hurston, told the stories of Black life with pride, humor and honesty. Musicians in the same period created jazz and blues, and their rhythms influenced poetry.\n\nFeatures of Harlem Renaissance writing:\n1. Pride in Black culture and history.\n2. Rhythms from jazz, blues and spirituals.\n3. Themes of identity, hope, dignity and struggle.\n4. Vivid images from daily life.\n\nThe theme of identity is a universal theme found across eras and cultures. Writers ask: Who am I? Where do I belong? What do I hope for?\n\nRead this original poem in the Harlem Renaissance spirit:\n\nI am the song my mother hummed\nwhile she scrubbed the morning floor.\nI am the hope she folded small\nand kept behind the door.\nNow I unfold it, bright and wide,\nand let the whole street sing.\n\nRhythm: steady, like a spiritual or blues. Image: the hope folded small, then unfolded. Theme: identity and hope passed from one generation to another.\n\nComparison with Scripture: Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made. Dignity and identity are rooted in God's creation.\n\nYour task: (1) Name two features of Harlem Renaissance writing found in the poem. (2) Explain the image of hope folded small. (3) State the universal theme and connect it to Psalm 139:14.\n\nFlorida standards: ELA.11.R.1.2, ELA.11.R.3.3, ELA.11.R.1.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.2, ELA.11.R.3.3, ELA.11.R.1.4", "script": "Now we visit a time and a place that changed American art forever. The Harlem Renaissance was a flowering of African American art, music and literature, centered in the Harlem neighborhood of New York City in the nineteen twenties and thirties.\n\nListen to some of the voices. Langston Hughes and Countee Cullen were poets. Zora Neale Hurston was a writer who told stories of Black life with humor and honesty. Musicians in the same period created jazz and blues, and their rhythms flowed into poetry.\n\nNow watch this. Here are the features of Harlem Renaissance writing. Pride in Black culture and history. Rhythms from jazz, blues and spirituals. Themes of identity, hope, dignity and struggle. And vivid images from daily life.\n\nIdentity is a universal theme. Writers ask, who am I? Where do I belong? What do I hope for? Those questions appear in every era and every culture.\n\nLet us read an original poem in that spirit. I am the song my mother hummed while she scrubbed the morning floor. I am the hope she folded small and kept behind the door. Now I unfold it, bright and wide, and let the whole street sing.\n\nThe rhythm is steady, like a spiritual or a blues song. The image is hope folded small and then unfolded. And the theme is identity and hope passed from one generation to the next.\n\nScripture speaks right into this. Psalm one hundred thirty nine, verse fourteen says, I will praise thee; for I am fearfully and wonderfully made. Dignity and identity are rooted in God's creation.\n\nYour task today. Name two features of Harlem Renaissance writing found in the poem. Explain the image of hope folded small. And state the universal theme and connect it to Psalm one hundred thirty nine, verse fourteen. Take the four question check when you finish.\n\nYou were made with purpose, and your voice matters. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The Harlem Renaissance$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Fitzgerald, Hemingway and the Style of the Jazz Age$j$, $j${"readings": [{"title": "Psalm 90 (King James Version)", "url": "/portal/bible/Psalms/90"}], "body": "F. Scott Fitzgerald and Ernest Hemingway wrote about the same decade, the 1920s, but in very different styles.\n\nFitzgerald wrote about wealth, parties and the American dream. His language is rich and lyrical, full of vivid images. His famous novel The Great Gatsby explores how the dream of success can become empty when it forgets love and honesty.\n\nHemingway used short, direct sentences and simple words. He believed that the deepest feeling could be shown by what is left unsaid. This approach is sometimes called the iceberg theory: most of the meaning lies beneath the surface.\n\nCompare the two styles:\nFitzgerald: rich images, longer sentences, strong symbols (a green light, a valley of ashes).\nHemingway: short sentences, plain words, hidden meaning.\n\nRead these two original passages about the same subject, a quiet train station:\n\nPassage A, in a rich style: The station glowed in the soft gold of evening, its windows catching the last light like old coins, and the people waiting seemed to hold their breath between one life and the next.\n\nPassage B, in a plain style: The station was quiet. A man sat on the bench with his hat on his knee. He did not look at the clock. The train was late.\n\nComparison: A uses simile, rich images and longer sentences to create a dreamy mood. B uses short sentences and hints at worry through what the man does not do. Both show waiting, but A tells through beauty and B through restraint.\n\nYour task: (1) Name the mood of each passage. (2) Quote one technique from each. (3) Explain which style you find more powerful and why.\n\nFlorida standards: ELA.11.R.1.1, ELA.11.R.1.3, ELA.11.R.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.1, ELA.11.R.1.3, ELA.11.R.3.3", "script": "Now we compare two giants of the nineteen twenties, F. Scott Fitzgerald and Ernest Hemingway. They wrote about the same decade, but in very different styles.\n\nFitzgerald wrote about wealth, parties and the American dream. His language is rich and lyrical, full of vivid images. In The Great Gatsby, he explores how the dream of success can become empty when it forgets love and honesty.\n\nHemingway used short, direct sentences and simple words. He believed the deepest feeling could be shown by what is left unsaid. This is sometimes called the iceberg theory. Most of the meaning lies beneath the surface.\n\nWatch this. Here is the comparison. Fitzgerald uses rich images, longer sentences and strong symbols, like a green light or a valley of ashes. Hemingway uses short sentences, plain words and hidden meaning.\n\nLet us read two original passages about a quiet train station.\n\nPassage A, in a rich style. The station glowed in the soft gold of evening, its windows catching the last light like old coins, and the people waiting seemed to hold their breath between one life and the next.\n\nPassage B, in a plain style. The station was quiet. A man sat on the bench with his hat on his knee. He did not look at the clock. The train was late.\n\nPassage A uses a simile, rich images and longer sentences to create a dreamy mood. Passage B uses short sentences and hints at worry through what the man does not do. Both show waiting, but A tells through beauty and B through restraint.\n\nYour task today. Name the mood of each passage. Quote one technique from each. And explain which style you find more powerful and why. Take the four question check when you finish.\n\nWhether in many words or few, let your words be true. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Fitzgerald, Hemingway and the Style of the Jazz Age$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Word Origins: Greek and Latin Roots in Literary Language$j$, $j${"readings": [{"title": "Ecclesiastes 2 (King James Version)", "url": "/portal/bible/Ecclesiastes/2"}], "body": "Many English words come from Greek and Latin. Learning roots, prefixes and suffixes helps you understand hard words in literature and in other subjects.\n\nCommon roots:\n1. bene (Latin): good or well. Examples: benefit, benevolent.\n2. mal (Latin): bad. Examples: malice, malevolent.\n3. scrib or script (Latin): write. Examples: describe, manuscript.\n4. graph (Greek): write or draw. Examples: autograph, biography.\n5. bio (Greek): life. Examples: biology, biography.\n6. chron (Greek): time. Examples: chronology, chronicle.\n7. spect (Latin): look. Examples: inspect, spectator.\n8. dict (Latin): say. Examples: dictate, predict.\n\nCommon prefixes: pre (before), post (after), anti (against), re (again), un (not), inter (between).\nCommon suffixes: ology (study of), ous (full of), ment (result of), ive (inclined to).\n\nExample analysis: The word benevolent combines bene (good) and vol (wish), so it means wishing good to others. The word manuscript combines manu (hand) and script (write), so it means something written by hand.\n\nUse word parts in context. If a character is described as malevolent, the reader can guess that the character wishes harm.\n\nAcademic vocabulary for this course: analyze, evidence, thesis, context, infer, perspective, rhetoric, theme.\n\nScripture: Philippians 4:8 says, Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.\n\nYour task: (1) Use word parts to define biography, benevolent and chronology. (2) Choose two academic words and use each in a sentence about a story you have read. (3) Write a sentence using a word with a Latin root from the list.\n\nFlorida standards: ELA.11.V.1.2, ELA.11.V.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.V.1.2, ELA.11.V.1.1", "script": "Today we look underneath words to see where they come from. Many English words come from Greek and Latin. When you learn roots, prefixes and suffixes, you can understand hard words in literature and in every other subject.\n\nListen to some common roots. Bene is Latin for good or well, as in benefit and benevolent. Mal is Latin for bad, as in malice and malevolent. Scrib or script is Latin for write, as in describe and manuscript. Graph is Greek for write or draw, as in autograph and biography. Bio is Greek for life, as in biology. Chron is Greek for time, as in chronology and chronicle. Spect is Latin for look, as in inspect and spectator. And dict is Latin for say, as in dictate and predict.\n\nNow watch this. Prefixes go at the beginning. Pre means before. Post means after. Anti means against. Re means again. Un means not. Inter means between. Suffixes go at the end. Ology means study of. Ous means full of. Ment means result of. Ive means inclined to.\n\nLet us practice. The word benevolent combines bene, good, and vol, wish, so it means wishing good to others. The word manuscript combines manu, hand, and script, write, so it means something written by hand. And if a character is described as malevolent, the reader can guess that the character wishes harm.\n\nOur academic vocabulary for this course includes analyze, evidence, thesis, context, infer, perspective, rhetoric and theme. Use these words as you write.\n\nAnd let your mind dwell on good things. Philippians chapter four, verse eight says, Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.\n\nYour task today. Use word parts to define biography, benevolent and chronology. Choose two academic words and use each in a sentence about a story you have read. And write a sentence using a word with a Latin root from the list. Take the four question check when you finish.\n\nA rich vocabulary opens a wide world. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Word Origins: Greek and Latin Roots in Literary Language$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Comparing Two Styles of the Same Era$j$, $j${"prompt": "Read these two original passages about the same subject, a family at a kitchen table at the end of a long war, and write a comparison of at least 150 words.\n\nPassage A: The lamp made a small gold room of the table, and in that room the family sat like figures in an old painting, each face carved by the same long winter of waiting. The bread was warm, the silence was warmer, and no one dared to name the empty chair.\n\nPassage B: They ate. The father cut the bread. The mother looked at the chair. Nobody said anything. The lamp was low.\n\nIn your comparison: (1) Name the mood of each passage. (2) Identify at least two techniques in each, such as imagery, simile, short sentences, understatement or symbol, and quote them. (3) Explain how each passage reflects the concerns of a period after a long war, such as loss and quiet hope. (4) Judge which style is more effective for the subject and give two reasons. (5) Connect the theme of loss and comfort to Psalm 34:18, which says, The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit. (6) Use complete sentences with a clear introduction and conclusion.", "rubric": "100 points. Mood of each passage: 15 points. Techniques with quotations: 25 points. Historical concerns explained: 15 points. Judgment of effectiveness with reasons: 20 points. Scripture connection: 15 points. Grammar and organization: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Comparing Two Styles of the Same Era$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Finding Hope After Loss$j$, $j${"prompt": "The writers of the Modern Era and the Harlem Renaissance wrote about loss, identity and hope. Write a post of at least 120 words that (1) explains why writers turn to poetry and stories after a time of great loss, (2) describes how art, music or reading has helped you or someone you know find hope, (3) tells which writer or style from this unit you would like to read more and why, and (4) connects your answer to Psalm 34:18, which says, The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit. Then write a respectful reply of at least 40 words to another student, or answer this question: How can a community help its members heal after a hard season? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Finding Hope After Loss$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Modernism and a Changing World$j$, $j${"questions": [{"q": "Modernism often uses:", "options": ["Plain language and subtle meaning", "Only long rhymed verses", "Only fairy tales", "No words"]}, {"q": "Disillusionment means:", "options": ["A new building", "Great joy", "A feeling that old promises have failed", "A kind of rhyme"]}, {"q": "World War I affected writers by:", "options": ["Making them stop writing forever", "Having no effect", "Shaking confidence and shaping their themes", "Making all writing rhyme"]}, {"q": "Joel 2:25 promises:", "options": ["Restoration of the years the locust ate", "No hope", "Another famine", "Silence"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Modernism and a Changing World$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,0}'::int[], array[$j$Modernists often used direct language with deeper meaning.$j$,$j$Disillusionment is the loss of illusions.$j$,$j$The war shaped the concerns of the era.$j$,$j$Joel 2:25 says God will restore the years that the locust hath eaten.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Modernism and a Changing World$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The Harlem Renaissance$j$, $j${"questions": [{"q": "The Harlem Renaissance centered in:", "options": ["San Francisco", "Miami only", "Harlem, New York City", "Boston harbor"]}, {"q": "Langston Hughes was a:", "options": ["Civil War general", "Frontier scout", "Poet of the Harlem Renaissance", "Colonial governor"]}, {"q": "Harlem Renaissance writing often reflects rhythms of:", "options": ["Only chants", "Jazz, blues and spirituals", "Only lullabies", "Only military marches"]}, {"q": "Psalm 139:14 says we are:", "options": ["Unknown", "Left alone", "Fearfully and wonderfully made", "Forgotten"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Harlem Renaissance$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,2}'::int[], array[$j$It centered in Harlem during the 1920s and 1930s.$j$,$j$Hughes was a major Harlem Renaissance poet.$j$,$j$Writers drew on the music of their community.$j$,$j$Psalm 139:14 says fearfully and wonderfully made.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Harlem Renaissance$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Fitzgerald, Hemingway and the Style of the Jazz Age$j$, $j${"questions": [{"q": "Hemingway's style is known for:", "options": ["Very long, ornate sentences", "Only dialect", "Only rhyme", "Short, direct sentences and hidden meaning"]}, {"q": "The iceberg theory suggests:", "options": ["Most meaning lies beneath the surface", "Stories should be about ice", "Stories should have no characters", "Everything must be said aloud"]}, {"q": "Fitzgerald is known for:", "options": ["Only plays", "Rich, lyrical language and vivid images", "Only poetry", "Plain, minimal style"]}, {"q": "A simile uses:", "options": ["A date", "A title", "Like or as", "Rhyme"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Fitzgerald, Hemingway and the Style of the Jazz Age$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,2}'::int[], array[$j$Hemingway used plain words and unspoken meaning.$j$,$j$Hemingway left much unsaid.$j$,$j$Fitzgerald wrote lyrical, image filled prose.$j$,$j$A simile uses like or as.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Fitzgerald, Hemingway and the Style of the Jazz Age$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Word Origins: Greek and Latin Roots in Literary Language$j$, $j${"questions": [{"q": "The Greek root bio means:", "options": ["Life", "Look", "Write", "Time"]}, {"q": "The root chron means:", "options": ["Life", "Good", "Time", "Say"]}, {"q": "The word benevolent most nearly means:", "options": ["Wishing harm to others", "Looking carefully", "Writing by hand", "Wishing good to others"]}, {"q": "The prefix anti means:", "options": ["Between", "Before", "After", "Against"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Word Origins: Greek and Latin Roots in Literary Language$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3}'::int[], array[$j$Bio means life.$j$,$j$Chron means time.$j$,$j$Bene means good and vol means wish.$j$,$j$Anti means against.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Word Origins: Greek and Latin Roots in Literary Language$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: The Modern Era and the Harlem Renaissance$j$, $j${"questions": [{"q": "Modernism often shows:", "options": ["Only battle plans", "Only fairy tales", "Plain language and subtle meaning", "Only long rhyme"]}, {"q": "The Harlem Renaissance took place mainly in:", "options": ["The 1920s and 1930s", "The 1800s", "The 1990s", "The 1700s"]}, {"q": "Hemingway's iceberg theory means:", "options": ["Stories must be cold", "All meaning is stated", "Most meaning lies beneath the surface", "Stories must have no people"]}, {"q": "A universal theme of identity asks:", "options": ["Who am I and where do I belong?", "What is the price?", "How far is the town?", "What is the date?"]}, {"q": "The Latin root dict means:", "options": ["Time", "Write", "Say", "Look"]}, {"q": "The root bio means:", "options": ["Time", "Hand", "Life", "Say"]}, {"q": "Disillusionment is:", "options": ["A feeling of joy", "A feeling that old promises failed", "A type of poem", "A kind of rhyme"]}, {"q": "Psalm 34:18 says the LORD is nigh unto them that are:", "options": ["Careless", "Of a broken heart", "Rich", "Proud"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Modern Era and the Harlem Renaissance$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,0,2,2,1,1}'::int[], array[$j$Modernists often used direct language with deeper meaning.$j$,$j$It flourished in the 1920s and 1930s.$j$,$j$The meaning is mostly unspoken.$j$,$j$Identity is a universal theme.$j$,$j$Dict means say.$j$,$j$Bio means life.$j$,$j$Disillusionment is lost faith in old promises.$j$,$j$Psalm 34:18 says the LORD is nigh unto them that are of a broken heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: The Modern Era and the Harlem Renaissance$j$ on conflict (item_id) do nothing;
